SourceCode.Declaration:
/// <summary>
/// Indirect cost matrix: selects the indirect component group of an hour line
/// from the worker's employment category and cost center (Table / Group / All on each axis).
/// The All / All line is the fallback (e.g. group CC).
/// </summary>
public class HOGpmaIndirectCostMatrix extends common
{
}

Method.Source:
/// <summary>
/// Clears the relation when its code changes.
/// </summary>
/// <param name = "_fieldId">The ID of the modified field.</param>
public void modifiedField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(HOGpmaIndirectCostMatrix, EmploymentCategoryCode):
            this.EmploymentCategoryRelation = '';
            break;

        case fieldNum(HOGpmaIndirectCostMatrix, CostCenterCode):
            this.CostCenterRelation = '';
            break;
    }
}

/// <summary>
/// Validates the code and relation of both axes.
/// </summary>
/// <returns>true if the record is valid; otherwise, false.</returns>
public boolean validateWrite()
{
    boolean ret = super();

    ret = this.checkRelation(
            this.EmploymentCategoryCode,
            this.EmploymentCategoryRelation,
            fieldNum(HOGpmaIndirectCostMatrix, EmploymentCategoryCode),
            fieldNum(HOGpmaIndirectCostMatrix, EmploymentCategoryRelation)) && ret;

    ret = this.checkRelation(
            this.CostCenterCode,
            this.CostCenterRelation,
            fieldNum(HOGpmaIndirectCostMatrix, CostCenterCode),
            fieldNum(HOGpmaIndirectCostMatrix, CostCenterRelation)) && ret;

    if (ret)
    {
        ret = this.checkRelationExists();
    }

    return ret;
}

/// <summary>
/// Checks that the relation is filled for Table and Group, and empty for All.
/// </summary>
/// <param name = "_code">The code of the axis.</param>
/// <param name = "_relation">The relation of the axis.</param>
/// <param name = "_codeFieldId">The field ID of the code.</param>
/// <param name = "_relationFieldId">The field ID of the relation.</param>
/// <returns>true if the combination is valid; otherwise, false.</returns>
private boolean checkRelation(
    TableGroupAll   _code,
    str             _relation,
    FieldId         _codeFieldId,
    FieldId         _relationFieldId)
{
    boolean ret = true;
    str     relationLabel = fieldId2PName(tableNum(HOGpmaIndirectCostMatrix), _relationFieldId);

    if (_code == TableGroupAll::All)
    {
        if (_relation)
        {
            ret = checkFailed(strFmt("@HOGpma:ErrRelationNotAllowed",
                relationLabel,
                fieldId2PName(tableNum(HOGpmaIndirectCostMatrix), _codeFieldId)));
        }
    }
    else if (!_relation)
    {
        ret = checkFailed(strFmt("@HOGpma:ErrRelationRequired", relationLabel));
    }

    return ret;
}

/// <summary>
/// Checks that the employment category, the employment category group and the cost center group exist.
/// </summary>
/// <returns>true if all referenced records exist; otherwise, false.</returns>
/// <remarks>
/// A cost center on the Table level is not validated against the dimension values (VERIFY: add a check
/// against the cost center dimension from <c>ProjParameters.HOGpmaCostCenterDimensionAttribute</c>).
/// </remarks>
private boolean checkRelationExists()
{
    boolean                     ret = true;
    BenefitEmploymentCategory   category;

    switch (this.EmploymentCategoryCode)
    {
        case TableGroupAll::Table:
            select firstonly RecId from category
                where category.EmploymentCategory == this.EmploymentCategoryRelation;

            if (!category.RecId)
            {
                ret = checkFailed(strFmt("@HOGpma:ErrValueNotFound",
                    tableId2PName(tableNum(BenefitEmploymentCategory)), this.EmploymentCategoryRelation));
            }
            break;

        case TableGroupAll::GroupId:
            if (!HOGpmaEmploymentCategoryGroup::exist(this.EmploymentCategoryRelation))
            {
                ret = checkFailed(strFmt("@HOGpma:ErrValueNotFound",
                    tableId2PName(tableNum(HOGpmaEmploymentCategoryGroup)), this.EmploymentCategoryRelation));
            }
            break;
    }

    if (this.CostCenterCode == TableGroupAll::GroupId
        && !HOGpmaCostCenterGroup::exist(this.CostCenterRelation))
    {
        ret = checkFailed(strFmt("@HOGpma:ErrValueNotFound",
            tableId2PName(tableNum(HOGpmaCostCenterGroup)), this.CostCenterRelation));
    }

    return ret;
}
